<?php declare(strict_types=1);
try{
 $revision=input($_GET,'area_original');$sha=input($_GET,'area_original_sha256');
 if(!preg_match('/\A(?:[1-9][0-9]{0,2}|1000)\z/D',$revision)||!preg_match('/\A[a-f0-9]{64}\z/D',$sha))throw new DomainException('Ursprüngliche Bereichsaufteilung vollständig auswählen.',404);
 $originalState=$areaService->originalState($periodId,(int)$revision,$sha);$record=end($originalState['history']);$units=$record['input']['units'];$proof=$record['proof'];$source=$record['source'];
}catch(DomainException|JsonException $ex){echo '<section class="card" role="alert"><h1>'.e($areaText('Bereichsaufteilung')).'</h1><p>'.e($areaText($ex->getMessage())).'</p><a href="'.e(url($areaHome)).'">'.e($areaText('Aktuelle Bereichsaufteilung öffnen')).'</a></section>';return;}
$current=null;$currentError='';try{$current=$areaService->view($periodId);}catch(DomainException|JsonException$ex){$currentError=$ex->getMessage();}
$sourceUrl=['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId,'period_source_sha256'=>$source['closed_sha256']];
$prior=$originalState['prior'];$priorUrl=null;
if($prior!==null){
 if(str_starts_with($prior['period_id'],'calendar:')){preg_match('/\Acalendar:([0-9]{4}):(segments|clearing)\z/D',$prior['period_id'],$m);$key=$m[2]==='clearing'?'clearing':'segment';$priorUrl=['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>$m[1],$key==='clearing'?'clearings':'segments'=>'1',$key.'_original'=>(string)$prior['version'],$key.'_original_sha256'=>$prior['sha256']];}
 else $priorUrl=['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$prior['period_id'],'areas'=>'1','area_original'=>(string)$prior['version'],'area_original_sha256'=>$prior['sha256']];
}
$at=(new DateTimeImmutable($record['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i');
?>
<link rel="stylesheet" href="tax-guided.css?v=3"><div class="content" data-tax-guided data-period-area-original="<?= e($record['sha256']) ?>">
<section class="card"><h1><?= e($areaText('Bereichsaufteilung')) ?></h1><p><?= e($dateLabel($source['period']['start']).' – '.$dateLabel($source['period']['end'])) ?></p><dl><dt><?= e($areaText('Prüfstand')) ?></dt><dd><?= (int)$record['revision'] ?></dd><dt><?= e($areaText('Damals gespeichert')) ?></dt><dd><?= e($at) ?></dd><dt><?= e($areaText('Damals geprüfter Vermerk')) ?></dt><dd><?= e($record['note']) ?></dd><dt><?= e($areaText('Damals gespeicherter Status')) ?></dt><dd><?= e($areaText($record['state']==='reviewed'?'Bestätigt':'Entwurf')) ?></dd></dl><dl><dt><?= e($areaText('Ergebnis dieses Zeitraums')) ?></dt><dd data-area-original-whole><?= $money($source['calculation']['annual_result_cents']) ?></dd></dl><p><?= e($areaText('Dieser ursprüngliche Nachweis erteilt keine neue Freigabe.')) ?></p><a href="<?= e(url($areaHome)) ?>"><?= e($areaText('Aktuelle Bereichsaufteilung öffnen')) ?></a></section>
<section class="card" data-area-original-current><h2><?= e($areaText('Aktueller Stand getrennt')) ?></h2><?php if($current===null): ?><p role="status"><?= e($areaText($currentError)) ?></p><?php else: ?><p><?= e($areaText('Prüfstand')).' '.(int)$current['version'].' · '.e($areaText($current['current_approval']?'Aufteilung bestätigt.':'Prüfung der Aufteilung offen.')) ?></p><?php endif ?></section>
<section class="card"><h2><?= e($areaText('Ergebnisse je Bereich')) ?></h2><?php foreach($proof['statement']['units']??[]as$unit): ?><section><h3><?= e($unit['name']) ?></h3><dl><?php foreach(['income_cents'=>'Erträge','expense_cents'=>'Aufwendungen','annual_result_cents'=>'Ergebnis']as$key=>$label): ?><dt><?= e($areaText($label)) ?></dt><dd><?= $money($unit['totals'][$key]) ?></dd><?php endforeach ?></dl></section><?php endforeach ?><?php foreach($proof['issues']as$issue): ?><p role="alert"><?= e($areaText($issue)) ?></p><?php endforeach ?></section>
<details class="card"><summary><?= e($areaText('Damals geprüfte Buchungen, Anlagen und interne Zahlungen')) ?></summary><p><a data-area-original-source href="<?= e(url($sourceUrl)) ?>"><?= e($areaText('Ursprünglichen festgeschriebenen Buchungsstand öffnen')) ?></a></p><?php if($priorUrl!==null): ?><p><a data-area-original-prior href="<?= e(url($priorUrl)) ?>"><?= e($areaText('Tatsächlich übernommenen Bereichsvortrag öffnen')) ?></a></p><?php endif ?>
<?php foreach(\Kulturhus\Verein\BalanceSegmentCalculation::sources($source)as$key=>$row): ?><article data-area-original-line="<?= e($key) ?>"><h3><?= e($dateLabel($row['date']).' · '.$row['description']) ?></h3><p><?= e($source['accounts'][$row['line']['account']]['name']).' · '.$money($row['cents']) ?></p><ul><?php foreach($record['input']['allocations'][$key]['parts']??[]as$unit=>$amount): ?><li><?= e($units[$unit]['name']).': '.$money($amount) ?></li><?php endforeach ?></ul><p><?= e($record['input']['allocations'][$key]['reason']??'') ?></p></article><?php endforeach ?>
<?php foreach($source['asset_schedule']['items']??[]as$itemId=>$item):$share=$record['input']['asset_shares'][$itemId]??null; ?><article data-area-original-asset="<?= e($itemId) ?>"><h3><?= e($item['name']) ?></h3><p><?= e($areaText('Buchwert am Ende:')).' '.$money($item['schedule']['book_closing_cents']) ?></p><?php if($share!==null): ?><ul><?php foreach($share['weights']as$unit=>$weight): ?><li><?= e($units[$unit]['name']).': '.(int)$weight.' '.e($areaText(\Kulturhus\Verein\BalanceAssetAllocation::MEASURES[$share['measure']])) ?></li><?php endforeach ?></ul><p><?= e($share['reason']) ?></p><?php foreach($share['changes']??[]as$change): ?><h4><?= e($areaText('Geänderte Nutzung')).' · '.e($dateLabel($change['on'])) ?></h4><ul><?php foreach($change['weights']as$unit=>$weight): ?><li><?= e($units[$unit]['name']).': '.(int)$weight ?></li><?php endforeach ?></ul><p><?= e($change['reason']) ?></p><?php endforeach;endif ?></article><?php endforeach ?>
<?php foreach($proof['clearing']['cases']??[]as$key=>$case): ?><article data-area-original-advance="<?= e($key) ?>"><h3><?= e($units[$case['from']]['name'].' → '.$units[$case['to']]['name']) ?></h3><dl><?php foreach(['opening_cents'=>'Offen am Anfang','advanced_cents'=>'Vorschüsse','repaid_cents'=>'Rückzahlungen','closing_cents'=>'Offen am Ende']as$field=>$label): ?><dt><?= e($areaText($label)) ?></dt><dd><?= $money($case[$field]) ?></dd><?php endforeach ?></dl></article><?php endforeach ?></details></div>
